import{_ as a,c as t,o,ag as n}from"./chunks/framework.B-XtCDNB.js";const i="/images/shoreline.jpg",g=JSON.parse('{"title":"Day 1, Trip to Bellingham","description":"","frontmatter":{"title":"Day 1, Trip to Bellingham"},"headers":[],"relativePath":"articles/article-1.md","filePath":"articles/article-1.md"}'),r={name:"articles/article-1.md"};function l(s,e,h,d,c,m){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="monday-in-bellingham" tabindex="-1">Monday in Bellingham <a class="header-anchor" href="#monday-in-bellingham" aria-label="Permalink to &quot;Monday in Bellingham&quot;">​</a></h1><p>Good morning, it&#39;s Monday in Bellingham and today we have the weather we were always hoping for. Clear and cool, not a cloud in the sky. Unfortunately we won&#39;t be able to enjoy the whole day here because we are going home to Irvine today. No matter, we have the morning here and and walk around with no umbrellas and no raincoats. That&#39;s going to be fun!</p><h2 id="morning-activities" tabindex="-1">Morning activities <a class="header-anchor" href="#morning-activities" aria-label="Permalink to &quot;Morning activities&quot;">​</a></h2><p>Jane and Alex will come pick us up around 9:30am and we will probably go get a bit of breakfast before we go for a walk somewhere beautiful. There are really just so many beautiful places to take a walk in Bellingham. Yesterday we went to an old farm called Woodstock and walked the grounds. We got to see a beautiful view of the train crossing the bay with a gorgeous pine covered shoreline in the background.</p><p><img src="'+i+'" alt="Shoreline with traintracks"></p><h2 id="return-to-irvine" tabindex="-1">Return to Irvine <a class="header-anchor" href="#return-to-irvine" aria-label="Permalink to &quot;Return to Irvine&quot;">​</a></h2><p>This afternoon we will head to the airport and wend our way home to Irvine. I always enjoy traveling but it is also really nice to get home. We won&#39;t be able to pick up our pups until tomorrow morning because we get back too late to retrieve them from the Bone Adventure tonight.</p>',7)])])}const p=a(r,[["render",l]]);export{g as __pageData,p as default};
